package com.chatspellcheck;

import java.awt.Rectangle;
import net.runelite.api.FontTypeFace;
import net.runelite.api.widgets.Widget;
import net.runelite.api.widgets.WidgetTextAlignment;

/**
 * Computes the on-screen bounds of a substring of the chatbox input, shared by the overlay and
 * the right-click ignore menu so bounding-box logic isn't duplicated.
 *
 * The offsets passed in are into the raw typed text ({@link ChatInputTracker#currentTypedText}),
 * but the widget's rendered text isn't identical: public/clan chat ({@code Chatbox.INPUT}) wraps
 * it in a name/icon prefix and {@code <col=...>...</col>} formatting tags around both the typed
 * portion and the cursor glyph (e.g. {@code <img=2>Name: <col=0000ff>hello </col><col=0000ff>*</col>});
 * private messages ({@code Chatbox.MES_TEXT2}) just append the cursor directly
 * ({@code "hello*"}). Verified in-client for both: the raw typed text always appears as one
 * unbroken substring of the widget text, so its start is found with a plain substring search
 * rather than assuming a specific surrounding format.
 */
final class ChatInputGeometry
{
	private ChatInputGeometry()
	{
	}

	static Rectangle boundsOf(Widget inputWidget, String typedText, int startOffset, int endOffset)
	{
		if (inputWidget == null || typedText == null || typedText.isEmpty())
		{
			return null;
		}

		FontTypeFace font = inputWidget.getFont();
		String widgetText = inputWidget.getText();
		Rectangle widgetBounds = inputWidget.getBounds();
		if (font == null || widgetText == null || widgetBounds == null)
		{
			return null;
		}

		if (startOffset < 0 || endOffset > typedText.length() || startOffset >= endOffset)
		{
			return null;
		}

		int typedStartInWidget = findTypedTextStart(widgetText, typedText);
		if (typedStartInWidget < 0)
		{
			return null;
		}

		int widgetStart = typedStartInWidget + startOffset;
		int widgetEnd = typedStartInWidget + endOffset;
		if (widgetEnd > widgetText.length())
		{
			return null;
		}

		int xBefore = font.getTextWidth(widgetText.substring(0, widgetStart));
		int wordWidth = font.getTextWidth(widgetText.substring(widgetStart, widgetEnd));
		int textBlockStart = textBlockStart(inputWidget, font, widgetText, widgetBounds);

		return new Rectangle(textBlockStart + xBefore, widgetBounds.y, wordWidth, widgetBounds.height);
	}

	/**
	 * The on-screen position right after the currently typed text - i.e. where the cursor sits
	 * during normal (non mid-string-edit) typing. Used to anchor the suggestion box even when the
	 * word it's for has been fully backspaced away and there's no {@link FlaggedWord} bounds left
	 * to hang it off of.
	 */
	static Rectangle cursorBounds(Widget inputWidget, String typedText)
	{
		if (inputWidget == null || typedText == null)
		{
			return null;
		}

		FontTypeFace font = inputWidget.getFont();
		String widgetText = inputWidget.getText();
		Rectangle widgetBounds = inputWidget.getBounds();
		if (font == null || widgetText == null || widgetBounds == null)
		{
			return null;
		}

		int textBlockStart = textBlockStart(inputWidget, font, widgetText, widgetBounds);

		int cursorX;
		if (typedText.isEmpty())
		{
			cursorX = textBlockStart;
		}
		else
		{
			int typedStartInWidget = findTypedTextStart(widgetText, typedText);
			if (typedStartInWidget < 0)
			{
				return null;
			}

			int endInWidget = typedStartInWidget + typedText.length();
			if (endInWidget > widgetText.length())
			{
				return null;
			}

			cursorX = textBlockStart + font.getTextWidth(widgetText.substring(0, endInWidget));
		}

		return new Rectangle(cursorX, widgetBounds.y, 0, widgetBounds.height);
	}

	// Public chat's input line is left-aligned within its widget, but private-message text
	// (Chatbox.MES_TEXT2) is centered within a much wider container - assuming left-flush placed
	// the underline/suggestion well to the left of the actual glyphs (confirmed in-game).
	private static int textBlockStart(Widget inputWidget, FontTypeFace font, String widgetText, Rectangle widgetBounds)
	{
		int totalWidth = font.getTextWidth(widgetText);
		switch (inputWidget.getXTextAlignment())
		{
			case WidgetTextAlignment.CENTER:
				return widgetBounds.x + (widgetBounds.width - totalWidth) / 2;
			case WidgetTextAlignment.RIGHT:
				return widgetBounds.x + widgetBounds.width - totalWidth;
			default:
				return widgetBounds.x;
		}
	}

	static int findTypedTextStart(String widgetText, String typedText)
	{
		return widgetText.lastIndexOf(typedText);
	}
}

package com.chatspellcheck;

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.Objects;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.Getter;
import net.runelite.api.Client;
import net.runelite.api.events.ScriptPostFired;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.VarClientID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.eventbus.Subscribe;

/**
 * Recomputes the flagged-word list whenever the chatbox input text actually changes (never on a
 * tick or frame timer of our own). Overlay rendering, the right-click ignore menu, and the send
 * guard all read {@link #getFlaggedWords()} rather than re-deriving it themselves.
 *
 * Neither {@code VarClientStrChanged} nor a RuneLite {@code KeyListener} fires for chatbox
 * composition in this client (verified in-game: keystrokes are consumed by the client's own
 * input handling before RuneLite's KeyManager sees them, and the documented
 * {@code CHAT_TEXT_INPUT_REBUILD} clientscript never ran despite hundreds of other scripts
 * firing). {@link ScriptPostFired} does fire on essentially every client tick regardless of
 * script, so this treats it as a cheap "something happened, check the input" pulse: it re-reads
 * the var on every firing but only does the actual tokenize/dictionary work
 * ({@link #recompute}) when the text differs from what was last seen.
 *
 * Two different vars carry the typed text depending on mode, confirmed in-game:
 * {@code VarClientID.CHATINPUT} for public/clan/friends chat, and
 * {@code VarClientID.MESLAYERINPUT} for private messages (and other modal text entry, e.g. bank
 * search). {@link #currentTypedText} reads both and uses whichever is non-empty.
 *
 * Since we can never insert the correction ourselves, the suggestion for the word currently being
 * typed "pins" once shown: backspacing the misspelled word keeps showing that last-good
 * suggestion (rather than flickering through whatever each half-deleted fragment would suggest on
 * its own), for as long as at least one character of the word remains. The instant it's fully
 * backspaced away, the suggestion drops immediately rather than hovering with nothing left to
 * anchor to. Retyping keeps the pin as long as what's typed is a prefix of it; typing something
 * that isn't - or completing it - clears the pin and lets a fresh suggestion take over. See
 * {@link #currentWordSuggestion}, {@link #currentWordSuggestionSince} (for the overlay's optional
 * auto-hide timeout), and {@link #currentWordSuggestionMatchedLength} (how much of it matches
 * what's typed so far, so the overlay can color the "already typed" prefix differently).
 */
@Singleton
class ChatInputTracker
{
	private final Client client;
	private final SpellcheckDictionary dictionary;
	private final IgnoreListStore ignoreListStore;

	@Getter
	private volatile List<FlaggedWord> flaggedWords = Collections.emptyList();

	/** The suggestion to display for the word currently being typed (see class doc for pinning). */
	@Getter
	private volatile String currentWordSuggestion;

	/** When {@link #currentWordSuggestion} last changed value - lets the overlay time out a stale one. */
	@Getter
	private volatile long currentWordSuggestionSince;

	/** How many leading characters of {@link #currentWordSuggestion} match what's typed so far. */
	@Getter
	private volatile int currentWordSuggestionMatchedLength;

	private volatile String lastText = "";
	private volatile String lastTrailingWord = "";
	private volatile String lastTrailingWordFreshSuggestion;
	private volatile String pinnedSuggestion;

	@Inject
	ChatInputTracker(Client client, SpellcheckDictionary dictionary, IgnoreListStore ignoreListStore)
	{
		this.client = client;
		this.dictionary = dictionary;
		this.ignoreListStore = ignoreListStore;
	}

	@Subscribe
	public void onScriptPostFired(ScriptPostFired event)
	{
		String text = currentTypedText(client);

		if (!Objects.equals(text, lastText))
		{
			lastText = text;
			recompute(text);
		}
	}

	static String currentTypedText(Client client)
	{
		String chatbox = client.getVarcStrValue(VarClientID.CHATINPUT);
		if (chatbox != null && !chatbox.isEmpty())
		{
			return chatbox;
		}

		String mesLayer = client.getVarcStrValue(VarClientID.MESLAYERINPUT);
		return mesLayer != null ? mesLayer : "";
	}

	/**
	 * The widget that renders the current text-entry line. {@code Chatbox.INPUT} for
	 * public/clan/friends chat; private messages render into {@code Chatbox.MES_TEXT2} instead
	 * (confirmed in-game - {@code Chatbox.INPUT} stays hidden throughout PM composition).
	 */
	static Widget currentInputWidget(Client client)
	{
		Widget input = client.getWidget(InterfaceID.Chatbox.INPUT);
		if (input != null && !input.isHidden())
		{
			return input;
		}

		return client.getWidget(InterfaceID.Chatbox.MES_TEXT2);
	}

	void reset()
	{
		lastText = "";
		lastTrailingWord = "";
		lastTrailingWordFreshSuggestion = null;
		pinnedSuggestion = null;
		flaggedWords = Collections.emptyList();
		setCurrentWordSuggestion(null);
	}

	void recompute(String text)
	{
		if (!dictionary.isLoaded())
		{
			flaggedWords = Collections.emptyList();
			setCurrentWordSuggestion(null);
			return;
		}

		List<WordToken> tokens = WordTokenizer.tokenize(text);
		List<FlaggedWord> flagged = new ArrayList<>();
		for (WordToken token : tokens)
		{
			String word = token.getWord();
			if (dictionary.isCorrect(word) || ignoreListStore.contains(word))
			{
				continue;
			}

			String suggestion = dictionary.suggest(word).orElse(null);
			flagged.add(new FlaggedWord(word, token.getStartOffset(), token.getEndOffset(), suggestion));
		}

		flaggedWords = flagged;
		updateCurrentWordSuggestion(text, tokens, flagged);
	}

	private void updateCurrentWordSuggestion(String text, List<WordToken> tokens, List<FlaggedWord> flagged)
	{
		// The "trailing word" is whatever's being actively composed at the very end of the input
		// (an empty string once it's been fully backspaced away, or if the text ends in a
		// separator like a space).
		boolean endsWithWordChar = !text.isEmpty() && !tokens.isEmpty() && tokens.get(tokens.size() - 1).getEndOffset() == text.length();
		WordToken trailingToken = endsWithWordChar ? tokens.get(tokens.size() - 1) : null;
		String trailingWord = trailingToken != null ? trailingToken.getWord() : "";

		String freshSuggestion = null;
		if (trailingToken != null)
		{
			for (FlaggedWord word : flagged)
			{
				if (word.getStartOffset() == trailingToken.getStartOffset() && word.getEndOffset() == trailingToken.getEndOffset())
				{
					freshSuggestion = word.getSuggestion();
					break;
				}
			}
		}

		if (trailingWord.isEmpty())
		{
			// Fully backspaced away (or nothing typed): drop the suggestion immediately rather
			// than leaving it hovering with no word left to anchor it to.
			pinnedSuggestion = null;
			setCurrentWordSuggestion(null);
			lastTrailingWord = trailingWord;
			lastTrailingWordFreshSuggestion = null;
			return;
		}

		boolean shrinking = trailingWord.length() < lastTrailingWord.length();

		if (pinnedSuggestion != null)
		{
			// Still being backspaced away: keep the pin no matter what the shrinking fragment
			// looks like (it's misspelled precisely because it doesn't align with the
			// suggestion). Only once the user starts typing again do we check consistency.
			if (!shrinking)
			{
				if (trailingWord.equalsIgnoreCase(pinnedSuggestion) || !pinnedSuggestion.startsWith(trailingWord.toLowerCase()))
				{
					pinnedSuggestion = null;
				}
			}
		}
		else if (shrinking && lastTrailingWordFreshSuggestion != null)
		{
			// Backspacing just started on a word that had a suggestion: pin it.
			pinnedSuggestion = lastTrailingWordFreshSuggestion;
		}

		setCurrentWordSuggestion(pinnedSuggestion != null ? pinnedSuggestion : freshSuggestion, trailingWord);
		lastTrailingWord = trailingWord;
		lastTrailingWordFreshSuggestion = freshSuggestion;
	}

	private void setCurrentWordSuggestion(String suggestion)
	{
		setCurrentWordSuggestion(suggestion, "");
	}

	private void setCurrentWordSuggestion(String suggestion, String trailingWord)
	{
		if (!Objects.equals(suggestion, currentWordSuggestion))
		{
			currentWordSuggestionSince = System.currentTimeMillis();
		}
		currentWordSuggestion = suggestion;
		currentWordSuggestionMatchedLength = (suggestion != null && suggestion.startsWith(trailingWord.toLowerCase()))
			? trailingWord.length() : 0;
	}
}

package com.chatspellcheck;

import java.awt.Color;
import net.runelite.client.config.Alpha;
import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.ConfigSection;
import net.runelite.client.config.Range;

@ConfigGroup(IgnoreListStore.CONFIG_GROUP)
public interface ChatSpellcheckConfig extends Config
{
	@ConfigSection(
		name = "Appearance",
		description = "Colors and sizing for the underline and suggestion box.",
		position = 10
	)
	String appearanceSection = "appearance";

	@ConfigItem(
		keyName = "blockOnTypos",
		name = "Block send on typos",
		description = "Pressing Enter with likely typos present shows a confirmation instead of sending immediately.",
		position = 1
	)
	default boolean blockOnTypos()
	{
		return true;
	}

	@ConfigItem(
		keyName = "highlightMisspelledWords",
		name = "Highlight misspelled words",
		description = "Underlines likely misspelled words in the chatbox input and shows a suggestion.",
		position = 2
	)
	default boolean highlightMisspelledWords()
	{
		return true;
	}

	@ConfigItem(
		keyName = "suggestionTimeoutEnabled",
		name = "Suggestion auto-hide",
		description = "Hides the suggestion box after it's been sitting idle for the timeout below, so it doesn't linger indefinitely.",
		position = 3
	)
	default boolean suggestionTimeoutEnabled()
	{
		return true;
	}

	@Range(min = 1, max = 60)
	@ConfigItem(
		keyName = "suggestionTimeoutSeconds",
		name = "Suggestion timeout (seconds)",
		description = "How long the suggestion box stays visible after it stops changing, if auto-hide is on.",
		position = 4
	)
	default int suggestionTimeoutSeconds()
	{
		return 5;
	}

	@ConfigItem(
		keyName = IgnoreListStore.IGNORE_LIST_KEY,
		name = "Ignored words",
		description = "Words the spellchecker won't flag. Comma-separated - remove a word here to un-ignore it.",
		position = 5
	)
	default String ignoreList()
	{
		return "";
	}

	@Range(min = 8, max = 32)
	@ConfigItem(
		keyName = "suggestionFontSize",
		name = "Font size",
		description = "Text size for the suggestion box. The box grows or shrinks to fit.",
		position = 11,
		section = appearanceSection
	)
	default int suggestionFontSize()
	{
		return 16;
	}

	@Alpha
	@ConfigItem(
		keyName = "underlineColor",
		name = "Underline color",
		description = "Color of the underline drawn beneath misspelled words.",
		position = 12,
		section = appearanceSection
	)
	default Color underlineColor()
	{
		return new Color(255, 64, 64);
	}

	@Alpha
	@ConfigItem(
		keyName = "suggestionTypedColor",
		name = "Suggestion: typed text color",
		description = "Color of the part of the suggestion that matches what you've typed so far.",
		position = 13,
		section = appearanceSection
	)
	default Color suggestionTypedColor()
	{
		return new Color(140, 255, 140);
	}

	@Alpha
	@ConfigItem(
		keyName = "suggestionRemainingColor",
		name = "Suggestion: remaining text color",
		description = "Color of the part of the suggestion you haven't typed yet.",
		position = 14,
		section = appearanceSection
	)
	default Color suggestionRemainingColor()
	{
		return new Color(255, 220, 150);
	}

	@Alpha
	@ConfigItem(
		keyName = "suggestionBackgroundColor",
		name = "Suggestion background",
		description = "Fill color of the suggestion box.",
		position = 15,
		section = appearanceSection
	)
	default Color suggestionBackgroundColor()
	{
		return new Color(20, 20, 20, 235);
	}

	@Alpha
	@ConfigItem(
		keyName = "suggestionBorderColor",
		name = "Suggestion border",
		description = "Outline color of the suggestion box.",
		position = 16,
		section = appearanceSection
	)
	default Color suggestionBorderColor()
	{
		return new Color(255, 180, 50);
	}

	@Alpha
	@ConfigItem(
		keyName = "blockedBannerTextColor",
		name = "Blocked-message text",
		description = "Text color of the \"message blocked\" notice shown after a send is blocked for typos.",
		position = 17,
		section = appearanceSection
	)
	default Color blockedBannerTextColor()
	{
		return new Color(255, 220, 150);
	}

	@Alpha
	@ConfigItem(
		keyName = "blockedBannerBackgroundColor",
		name = "Blocked-message background",
		description = "Fill color of the \"message blocked\" notice.",
		position = 18,
		section = appearanceSection
	)
	default Color blockedBannerBackgroundColor()
	{
		return new Color(20, 20, 20, 235);
	}

	@Alpha
	@ConfigItem(
		keyName = "blockedBannerBorderColor",
		name = "Blocked-message border",
		description = "Outline color of the \"message blocked\" notice.",
		position = 19,
		section = appearanceSection
	)
	default Color blockedBannerBorderColor()
	{
		return new Color(220, 60, 60);
	}

	@Alpha
	@ConfigItem(
		keyName = "ignoreMenuColor",
		name = "\"Ignore\" menu entry color",
		description = "Text color of the right-click \"Add to spellcheck ignore list\" menu entry.",
		position = 20,
		section = appearanceSection
	)
	default Color ignoreMenuColor()
	{
		return new Color(255, 180, 50);
	}
}

package com.chatspellcheck;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import java.util.List;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.FontTypeFace;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

/**
 * Draws an underline under each flagged word, a boxed suggestion label at the cursor for
 * {@link ChatInputTracker#getCurrentWordSuggestion()}, and a boxed "message blocked" notice
 * anchored at the input line. Only ever reads state already computed by {@link ChatInputTracker}
 * and {@link SendGuard} - never re-tokenizes or re-checks the dictionary itself, so per-frame
 * cost stays cheap.
 */
class ChatSpellcheckOverlay extends Overlay
{
	private static final int BOX_PADDING_X = 5;
	private static final int BOX_PADDING_Y = 3;
	private static final int BOX_GAP = 6;
	private static final long PM_BANNER_DURATION_MS = 3000;

	private final Client client;
	private final ChatInputTracker chatInputTracker;
	private final SendGuard sendGuard;
	private final ChatSpellcheckConfig config;

	@Inject
	ChatSpellcheckOverlay(Client client, ChatInputTracker chatInputTracker, SendGuard sendGuard, ChatSpellcheckConfig config)
	{
		this.client = client;
		this.chatInputTracker = chatInputTracker;
		this.sendGuard = sendGuard;
		this.config = config;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_WIDGETS);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		Widget inputWidget = ChatInputTracker.currentInputWidget(client);
		String typedText = ChatInputTracker.currentTypedText(client);
		boolean widgetUsable = inputWidget != null && !inputWidget.isHidden();

		if (config.blockOnTypos() && sendGuard.isPendingConfirmation()
			&& System.currentTimeMillis() - sendGuard.getPendingSince() < PM_BANNER_DURATION_MS)
		{
			// The client clears the input box on Enter regardless of whether we block the send
			// (confirmed in-game for both public/clan chat and private messages), and we can't
			// repopulate it ourselves - RuneLite's guidelines forbid programmatically inserting
			// text into the chatbox. So this is a timed notice rather than a persisted-text
			// comparison: it tells the player the message was blocked and to retype it, drawn
			// right at the (now-empty) input line rather than up in the chat history area.
			Rectangle anchor = bannerAnchor(inputWidget, widgetUsable, typedText);
			if (anchor != null)
			{
				renderConfirmBanner(graphics, anchor, "Typos found - message blocked, retype to send");
			}
		}

		if (widgetUsable && config.highlightMisspelledWords())
		{
			renderUnderlines(graphics, inputWidget, typedText);

			String suggestion = chatInputTracker.getCurrentWordSuggestion();
			boolean timedOut = config.suggestionTimeoutEnabled()
				&& System.currentTimeMillis() - chatInputTracker.getCurrentWordSuggestionSince() >= config.suggestionTimeoutSeconds() * 1000L;
			if (suggestion != null && !timedOut)
			{
				Rectangle cursor = ChatInputGeometry.cursorBounds(inputWidget, typedText);
				if (cursor != null)
				{
					renderSuggestionBox(graphics, cursor, suggestion, chatInputTracker.getCurrentWordSuggestionMatchedLength());
				}
			}
		}

		return null;
	}

	private void renderUnderlines(Graphics2D graphics, Widget inputWidget, String typedText)
	{
		List<FlaggedWord> flagged = chatInputTracker.getFlaggedWords();
		if (flagged.isEmpty())
		{
			return;
		}

		FontTypeFace widgetFont = inputWidget.getFont();
		graphics.setColor(config.underlineColor());

		for (FlaggedWord word : flagged)
		{
			Rectangle bounds = ChatInputGeometry.boundsOf(inputWidget, typedText, word.getStartOffset(), word.getEndOffset());
			if (bounds == null)
			{
				continue;
			}

			int y = bounds.y + (widgetFont != null ? widgetFont.getBaseline() + 2 : bounds.height - 1);
			graphics.drawLine(bounds.x, y, bounds.x + bounds.width, y);
		}
	}

	// Anchored to the cursor position rather than a specific word's bounds, since a pinned
	// suggestion (see ChatInputTracker) can still be showing after its word has been fully
	// backspaced away, when there's no FlaggedWord bounds left to hang it off of.
	private void renderSuggestionBox(Graphics2D graphics, Rectangle cursor, String suggestion, int matchedLength)
	{
		Font font = boxFont();
		graphics.setFont(font);
		FontMetrics metrics = graphics.getFontMetrics(font);

		Rectangle box = boxBounds(metrics, suggestion, cursor);
		drawBox(graphics, box, config.suggestionBackgroundColor(), config.suggestionBorderColor());

		String typedPart = suggestion.substring(0, matchedLength);
		String remainingPart = suggestion.substring(matchedLength);
		int textX = box.x + BOX_PADDING_X;
		int textY = box.y + BOX_PADDING_Y + metrics.getAscent();

		graphics.setColor(config.suggestionTypedColor());
		graphics.drawString(typedPart, textX, textY);

		graphics.setColor(config.suggestionRemainingColor());
		graphics.drawString(remainingPart, textX + metrics.stringWidth(typedPart), textY);
	}

	// Prefers the cursor position within the (now-empty, post-block) input line; falls back to
	// the whole chatbox container since the PM compose window can disappear entirely on Enter,
	// even when the send was blocked.
	private Rectangle bannerAnchor(Widget inputWidget, boolean widgetUsable, String typedText)
	{
		if (widgetUsable)
		{
			Rectangle cursor = ChatInputGeometry.cursorBounds(inputWidget, typedText);
			if (cursor != null)
			{
				return cursor;
			}
		}

		Widget fallback = client.getWidget(InterfaceID.Chatbox.UNIVERSE);
		if (fallback == null)
		{
			return null;
		}

		Rectangle bounds = fallback.getBounds();
		return new Rectangle(bounds.x, bounds.y, 0, bounds.height);
	}

	private void renderConfirmBanner(Graphics2D graphics, Rectangle anchor, String text)
	{
		Font font = boxFont();
		graphics.setFont(font);
		FontMetrics metrics = graphics.getFontMetrics(font);

		Rectangle box = boxBounds(metrics, text, anchor);
		drawBox(graphics, box, config.blockedBannerBackgroundColor(), config.blockedBannerBorderColor());

		graphics.setColor(config.blockedBannerTextColor());
		graphics.drawString(text, box.x + BOX_PADDING_X, box.y + BOX_PADDING_Y + metrics.getAscent());
	}

	// Derived from the game's own bitmap font rather than a fixed small/regular/large choice, so
	// the configured size is a plain point value and every box scales continuously with it.
	private Font boxFont()
	{
		return FontManager.getRunescapeFont().deriveFont((float) config.suggestionFontSize());
	}

	private static Rectangle boxBounds(FontMetrics metrics, String text, Rectangle anchor)
	{
		int textWidth = metrics.stringWidth(text);
		int boxWidth = textWidth + BOX_PADDING_X * 2;
		int boxHeight = metrics.getAscent() + metrics.getDescent() + BOX_PADDING_Y * 2;
		int boxX = anchor.x + BOX_GAP;
		int boxY = anchor.y + (anchor.height - boxHeight) / 2;
		return new Rectangle(boxX, boxY, boxWidth, boxHeight);
	}

	private static void drawBox(Graphics2D graphics, Rectangle box, Color background, Color border)
	{
		graphics.setColor(background);
		graphics.fillRoundRect(box.x, box.y, box.width, box.height, 5, 5);
		graphics.setColor(border);
		graphics.drawRoundRect(box.x, box.y, box.width, box.height, 5, 5);
	}
}

