package com.chatspellcheck;

import java.util.Collections;
import java.util.LinkedHashSet;
import java.util.Set;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;

/**
 * Persists user-added "don't flag this word" entries via {@link ConfigManager}, exposed as the
 * {@code ignoreList} {@code @ConfigItem} on {@link ChatSpellcheckConfig} so the user can review
 * and remove entries directly in the plugin's settings panel. Since edits can happen there
 * (bypassing {@link #add}), this also refreshes its in-memory copy on {@link ConfigChanged}.
 */
@Singleton
class IgnoreListStore
{
	static final String CONFIG_GROUP = "chat-spellcheck";
	static final String IGNORE_LIST_KEY = "ignoreList";
	private static final String DELIMITER = ",";

	private final ConfigManager configManager;
	private final Set<String> ignored = Collections.synchronizedSet(new LinkedHashSet<>());

	@Inject
	IgnoreListStore(ConfigManager configManager)
	{
		this.configManager = configManager;
	}

	void load()
	{
		String stored = configManager.getConfiguration(CONFIG_GROUP, IGNORE_LIST_KEY);
		ignored.clear();
		ignored.addAll(deserialize(stored));
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if (CONFIG_GROUP.equals(event.getGroup()) && IGNORE_LIST_KEY.equals(event.getKey()))
		{
			load();
		}
	}

	boolean contains(String word)
	{
		return ignored.contains(word.toLowerCase());
	}

	void add(String word)
	{
		String lower = word.toLowerCase();
		if (ignored.add(lower))
		{
			configManager.setConfiguration(CONFIG_GROUP, IGNORE_LIST_KEY, serialize(ignored));
		}
	}

	static String serialize(Set<String> words)
	{
		return String.join(DELIMITER, words);
	}

	static Set<String> deserialize(String stored)
	{
		if (stored == null || stored.trim().isEmpty())
		{
			return Collections.emptySet();
		}

		Set<String> result = new LinkedHashSet<>();
		for (String word : stored.split(DELIMITER))
		{
			String trimmed = word.trim();
			if (!trimmed.isEmpty())
			{
				result.add(trimmed.toLowerCase());
			}
		}
		return result;
	}
}

package com.chatspellcheck;

import java.util.Objects;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.Getter;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ChatInput;
import net.runelite.client.events.ChatboxInput;
import net.runelite.client.events.PrivateMessageInput;

/**
 * Intercepts the chatbox send action: if typos are present, consumes the event once (blocking
 * the send, per RuneLite's own {@code ChatInputManager}) and waits for a second, unmodified send
 * attempt before letting it through. Never alters the outgoing message and never injects input -
 * {@link ChatInput#consume()} is RuneLite's own sanctioned veto mechanism for this, the same one
 * its built-in chat-command handling uses. Public/clan/etc. chat and private messages fire as two
 * separate event types ({@link ChatboxInput} and {@link PrivateMessageInput}), so both are handled.
 *
 * The private-message compose window closes on Enter even when the send is blocked (confirmed
 * in-game - the client resets the input regardless of {@code consume()}), so there's no persisted
 * text left for a "type it again unchanged" comparison there. {@link #pendingSince} lets the
 * overlay show a timed banner in that case instead of relying on a text match.
 */
@Slf4j
@Singleton
class SendGuard
{
	private final ChatSpellcheckConfig config;
	private final ChatInputTracker chatInputTracker;

	@Getter
	private volatile boolean pendingConfirmation;
	@Getter
	private volatile String pendingText;
	@Getter
	private volatile long pendingSince;

	@Inject
	SendGuard(ChatSpellcheckConfig config, ChatInputTracker chatInputTracker)
	{
		this.config = config;
		this.chatInputTracker = chatInputTracker;
	}

	@Subscribe
	public void onChatboxInput(ChatboxInput event)
	{
		guard(event, event.getValue());
	}

	@Subscribe
	public void onPrivateMessageInput(PrivateMessageInput event)
	{
		guard(event, event.getMessage());
	}

	private void guard(ChatInput event, String text)
	{
		log.debug("Chat Spellcheck [diag]: guard text='{}' blockOnTypos={} flagged={}",
			text, config.blockOnTypos(), chatInputTracker.getFlaggedWords());

		if (!config.blockOnTypos())
		{
			return;
		}

		if (pendingConfirmation && Objects.equals(text, pendingText))
		{
			// Second send attempt with the text unchanged: let it through.
			clearPending();
			return;
		}

		if (!chatInputTracker.getFlaggedWords().isEmpty())
		{
			event.consume();
			pendingText = text;
			pendingSince = System.currentTimeMillis();
			pendingConfirmation = true;
		}
		else
		{
			clearPending();
		}
	}

	void reset()
	{
		clearPending();
	}

	private void clearPending()
	{
		pendingConfirmation = false;
		pendingText = null;
	}
}

package com.chatspellcheck;

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.nio.charset.StandardCharsets;
import java.util.Collections;
import java.util.HashMap;
import java.util.HashSet;
import java.util.Map;
import java.util.Optional;
import java.util.Set;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;

/**
 * Case-insensitive English word lookup plus Norvig-style single/double-edit-distance suggestions.
 * No client dependency: {@link #load()} is plain Java I/O so it's safe to call from a background
 * executor, and it fails open (leaves the dictionary "not loaded") on any error rather than
 * throwing, so a corrupt/missing resource can never break the plugin.
 */
@Slf4j
@Singleton
class SpellcheckDictionary
{
	private static final String ALPHABET = "abcdefghijklmnopqrstuvwxyz";
	private static final String[] PLAIN_RESOURCES = {
		"/com/chatspellcheck/dictionary-enable1.txt",
		"/com/chatspellcheck/osrs-terms.txt",
		"/com/chatspellcheck/contractions-en.txt"
	};
	private static final String FREQUENCY_RESOURCE = "/com/chatspellcheck/word-frequency-en.txt";

	private volatile Set<String> words = Collections.emptySet();
	// Lower rank = more common. Multiple equally-valid edit-distance candidates are ranked by
	// this so "world" wins over "wold" for "wrld" instead of an arbitrary HashSet order.
	private volatile Map<String, Integer> wordRank = Collections.emptyMap();
	private volatile boolean loaded = false;

	void load()
	{
		Set<String> loadedWords = new HashSet<>(220_000);
		Map<String, Integer> loadedRank = new HashMap<>(50_000);

		for (String resource : PLAIN_RESOURCES)
		{
			if (!loadResource(resource, loadedWords))
			{
				log.warn("Chat Spellcheck: failed to load dictionary resource {}, spellcheck disabled for this session", resource);
				return;
			}
		}

		if (!loadFrequencyResource(FREQUENCY_RESOURCE, loadedWords, loadedRank))
		{
			log.warn("Chat Spellcheck: failed to load dictionary resource {}, spellcheck disabled for this session", FREQUENCY_RESOURCE);
			return;
		}

		words = loadedWords;
		wordRank = loadedRank;
		loaded = true;
		log.debug("Chat Spellcheck: loaded {} words ({} ranked)", loadedWords.size(), loadedRank.size());
	}

	private boolean loadResource(String resource, Set<String> into)
	{
		try (InputStream is = SpellcheckDictionary.class.getResourceAsStream(resource))
		{
			if (is == null)
			{
				return false;
			}

			try (BufferedReader reader = new BufferedReader(new InputStreamReader(is, StandardCharsets.UTF_8)))
			{
				String line;
				while ((line = reader.readLine()) != null)
				{
					String word = line.trim().toLowerCase();
					if (!word.isEmpty())
					{
						into.add(word);
					}
				}
			}
			return true;
		}
		catch (IOException e)
		{
			log.warn("Chat Spellcheck: error reading dictionary resource {}", resource, e);
			return false;
		}
	}

	// Frequency-list entries are also union-ed into the correctness set: it's real English
	// vocabulary, and ENABLE1 (a word-game list) excludes short/common words like "a" and "i"
	// that would otherwise be incorrectly flagged as typos.
	private boolean loadFrequencyResource(String resource, Set<String> wordsOut, Map<String, Integer> rankOut)
	{
		try (InputStream is = SpellcheckDictionary.class.getResourceAsStream(resource))
		{
			if (is == null)
			{
				return false;
			}

			try (BufferedReader reader = new BufferedReader(new InputStreamReader(is, StandardCharsets.UTF_8)))
			{
				String line;
				int rank = 0;
				while ((line = reader.readLine()) != null)
				{
					String word = line.trim().toLowerCase();
					if (!word.isEmpty())
					{
						wordsOut.add(word);
						rankOut.putIfAbsent(word, rank);
						rank++;
					}
				}
			}
			return true;
		}
		catch (IOException e)
		{
			log.warn("Chat Spellcheck: error reading dictionary resource {}", resource, e);
			return false;
		}
	}

	boolean isLoaded()
	{
		return loaded;
	}

	boolean isCorrect(String word)
	{
		return words.contains(word.toLowerCase());
	}

	/** Returns the most common valid correction within edit distance 2, or empty if none found. */
	Optional<String> suggest(String word)
	{
		String lower = word.toLowerCase();

		Set<String> edits1 = editsOne(lower);
		Optional<String> best = bestCandidate(edits1);
		if (best.isPresent())
		{
			return best;
		}

		Set<String> edits2 = new HashSet<>();
		for (String e1 : edits1)
		{
			edits2.addAll(editsOne(e1));
		}
		return bestCandidate(edits2);
	}

	private Optional<String> bestCandidate(Set<String> candidates)
	{
		String best = null;
		int bestRank = Integer.MAX_VALUE;

		for (String candidate : candidates)
		{
			if (!isCorrect(candidate))
			{
				continue;
			}

			Integer rank = wordRank.get(candidate);
			if (rank != null)
			{
				if (rank < bestRank)
				{
					bestRank = rank;
					best = candidate;
				}
			}
			else if (best == null)
			{
				best = candidate;
			}
		}

		return Optional.ofNullable(best);
	}

	private static Set<String> editsOne(String word)
	{
		Set<String> result = new HashSet<>();
		for (int i = 0; i <= word.length(); i++)
		{
			String left = word.substring(0, i);
			String right = word.substring(i);

			if (!right.isEmpty())
			{
				// delete
				result.add(left + right.substring(1));
			}

			if (right.length() > 1)
			{
				// transpose
				result.add(left + right.charAt(1) + right.charAt(0) + right.substring(2));
			}

			if (!right.isEmpty())
			{
				// replace
				for (int c = 0; c < ALPHABET.length(); c++)
				{
					result.add(left + ALPHABET.charAt(c) + right.substring(1));
				}
			}

			// insert
			for (int c = 0; c < ALPHABET.length(); c++)
			{
				result.add(left + ALPHABET.charAt(c) + right);
			}
		}
		return result;
	}
}

package com.chatspellcheck;

import java.awt.Color;
import java.awt.Rectangle;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.MenuAction;
import net.runelite.api.MenuEntry;
import net.runelite.api.Point;
import net.runelite.api.events.MenuEntryAdded;
import net.runelite.api.widgets.Widget;
import net.runelite.client.eventbus.Subscribe;

/**
 * Adds a "add to spellcheck ignore list" entry when right-clicking a flagged word in the
 * chatbox input. Never adds entries that send an action to the server (MenuAction.RUNELITE is
 * handled entirely client-side).
 *
 * The menu's own background/panel is drawn natively by the client and isn't something a plugin
 * can restyle, but the option text color is - wrapped in the same {@code <col=RRGGBB>} tag OSRS
 * itself uses for menu entry text - so {@link ChatSpellcheckConfig#ignoreMenuColor()} controls
 * that.
 */
class SpellcheckMenuManager
{
	private final Client client;
	private final ChatInputTracker chatInputTracker;
	private final IgnoreListStore ignoreListStore;
	private final ChatSpellcheckConfig config;

	@Inject
	SpellcheckMenuManager(Client client, ChatInputTracker chatInputTracker, IgnoreListStore ignoreListStore, ChatSpellcheckConfig config)
	{
		this.client = client;
		this.chatInputTracker = chatInputTracker;
		this.ignoreListStore = ignoreListStore;
		this.config = config;
	}

	@Subscribe
	public void onMenuEntryAdded(MenuEntryAdded event)
	{
		if (chatInputTracker.getFlaggedWords().isEmpty())
		{
			return;
		}

		Widget inputWidget = ChatInputTracker.currentInputWidget(client);
		if (inputWidget == null || inputWidget.isHidden())
		{
			return;
		}

		String typedText = ChatInputTracker.currentTypedText(client);
		Point mouse = client.getMouseCanvasPosition();

		for (FlaggedWord word : chatInputTracker.getFlaggedWords())
		{
			Rectangle bounds = ChatInputGeometry.boundsOf(inputWidget, typedText, word.getStartOffset(), word.getEndOffset());
			if (bounds == null || !bounds.contains(mouse.getX(), mouse.getY()))
			{
				continue;
			}

			client.getMenu().createMenuEntry(-1)
				.setOption(colorTag(config.ignoreMenuColor()) + "Add '" + word.getWord() + "' to spellcheck ignore list</col>")
				.setTarget("")
				.setType(MenuAction.RUNELITE)
				.onClick(e -> onIgnoreClicked(word.getWord()));
			return;
		}
	}

	private void onIgnoreClicked(String word)
	{
		ignoreListStore.add(word);
		chatInputTracker.recompute(ChatInputTracker.currentTypedText(client));
	}

	private static String colorTag(Color color)
	{
		return String.format("<col=%02x%02x%02x>", color.getRed(), color.getGreen(), color.getBlue());
	}
}

package com.chatspellcheck;

import lombok.Value;

/** A word found by {@link WordTokenizer}, with its character offsets into the source string. */
@Value
public class WordToken
{
	String word;
	int startOffset;
	int endOffset;
}

package com.chatspellcheck;

import java.util.ArrayList;
import java.util.List;

/**
 * Splits chatbox input text into words with character offsets. A "word" is a maximal run of
 * letters/apostrophes (so contractions like "don't" stay one token); digits and punctuation are
 * treated as separators and never flagged.
 */
final class WordTokenizer
{
	private WordTokenizer()
	{
	}

	static List<WordToken> tokenize(String text)
	{
		List<WordToken> tokens = new ArrayList<>();
		if (text == null || text.isEmpty())
		{
			return tokens;
		}

		int start = -1;
		for (int i = 0; i <= text.length(); i++)
		{
			boolean isWordChar = i < text.length() && isWordChar(text.charAt(i));
			if (isWordChar)
			{
				if (start == -1)
				{
					start = i;
				}
			}
			else if (start != -1)
			{
				Trimmed trimmed = trimApostrophes(text, start, i);
				if (trimmed.endWord > trimmed.startWord)
				{
					tokens.add(new WordToken(text.substring(trimmed.startWord, trimmed.endWord), trimmed.startWord, trimmed.endWord));
				}
				start = -1;
			}
		}

		return tokens;
	}

	private static boolean isWordChar(char c)
	{
		return Character.isLetter(c) || c == '\'';
	}

	// Apostrophes at the very start/end of a run (e.g. quoting: 'word') aren't part of the word.
	private static Trimmed trimApostrophes(String text, int start, int end)
	{
		int s = start;
		int e = end;
		while (s < e && text.charAt(s) == '\'')
		{
			s++;
		}
		while (e > s && text.charAt(e - 1) == '\'')
		{
			e--;
		}
		return new Trimmed(s, e);
	}

	private static final class Trimmed
	{
		final int startWord;
		final int endWord;

		Trimmed(int startWord, int endWord)
		{
			this.startWord = startWord;
			this.endWord = endWord;
		}
	}
}

